/**
 * Calls Telegram getUpdates, extracts the first chat ID found, and persists it to disk. The user must send any message to the bot first.
 * @summary Auto-detect Telegram Chat ID from recent bot messages
 */
export const getDetectChatIdUrl = () => {
  return `/api/alerts/detect-chat-id`;
};

export const detectChatId = async (
  options?: RequestInit,
): Promise<DetectChatIdResult> => {
  return customFetch<DetectChatIdResult>(getDetectChatIdUrl(), {
    ...options,
    method: "POST",
  });
};

export const getDetectChatIdMutationOptions = <
  TError = ErrorType<DetectChatIdResult>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof detectChatId>>,
    TError,
    void,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof detectChatId>>,
  TError,
  void,
  TContext
> => {
  const mutationKey = ["detectChatId"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof detectChatId>>,
    void
  > = () => {
    return detectChatId(requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type DetectChatIdMutationResult = NonNullable<
  Awaited<ReturnType<typeof detectChatId>>
>;

export type DetectChatIdMutationError = ErrorType<DetectChatIdResult>;

/**
 * @summary Auto-detect Telegram Chat ID from recent bot messages
 */
export const useDetectChatId = <
  TError = ErrorType<DetectChatIdResult>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof detectChatId>>,
    TError,
    void,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof detectChatId>>,
  TError,
  void,
  TContext
> => {
  return useMutation(getDetectChatIdMutationOptions(options));
};
